import{_ as t,o as s,c as a,a5 as r}from"./chunks/framework.CslsFoWx.js";const m=JSON.parse('{"title":"Feuille de route","description":"","frontmatter":{},"headers":[],"relativePath":"produit/feuille-de-route.md","filePath":"produit/feuille-de-route.md","lastUpdated":1793475466000}'),o={name:"produit/feuille-de-route.md"};function i(n,e,l,d,u,p){return s(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="feuille-de-route" tabindex="-1">Feuille de route <a class="header-anchor" href="#feuille-de-route" aria-label="Permalink to &quot;Feuille de route&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Phase</th><th>Contenu</th><th>État</th></tr></thead><tbody><tr><td><strong>0 — Fondations</strong></td><td>Monorepo, CI, API Spring Boot, PostgreSQL + RLS multi-tenant, auth / rôles / appareils, moteur de calcul partagé et sa suite de référence, back-office minimal, <strong>POC sync offline + hub local</strong></td><td><span class="badge ok">Fait</span> 28/10/2026</td></tr><tr><td><strong>1 — La caisse</strong></td><td>Écran de vente &lt; 100 ms (scan douchette + caméra, boutons rapides), panier, remises, paiements multiples, tickets ESC/POS, sessions de caisse et rapports X/Z, stock signé, mode offline, étiquettes, PIN caissier et manager, socle fiscal (scellement, clôtures, archive, mode formation)</td><td><span class="badge ok">Fait</span> 29/10/2026</td></tr><tr><td><strong>2 — Restaurant et temps réel</strong></td><td>Plan de salle, additions, modificateurs, postes et bons cuisine, KDS, téléphone de salle, hub temps réel local, opérations sur additions, pourboires, encaissement à la table, fournisseurs de paiement (simulés), annulations et retours, personnalisation complète</td><td><span class="badge ok">Fait</span> 30/10/2026 (lots 2.1 → 2.22)</td></tr><tr><td><strong>Reliquats avant phase 3</strong></td><td>Caisse, équipe, personnalisation (langue + RTL, logo de marque, presets kiosque), restaurant (sécurité LAN, imprimeur unique), dette technique (version minimale, télémétrie), identité Ed25519</td><td><span class="badge ok">Fait</span> 30/10/2026 (lots 2.23 → 2.28)</td></tr><tr><td><strong>3 — Gestion complète et anti-fraude</strong></td><td><strong>Faits</strong> : clients, remises, fidélité, ardoise, reçus digitaux et QR client, fournisseurs et achats, dettes fournisseurs, inventaires mobiles et pertes, alertes stock et anti-fraude (lots 3.1 → 3.9). <strong>À faire</strong> : rapports et tableau de bord, multi-magasins, exports comptables / FEC, titres-restaurant, food-cost, e-reporting B2C France (3.10 → 3.15)</td><td><span class="badge partial">En cours</span> 3.1 → 3.9 faits le 31/10/2026 ; restes des fonctions partielles en cours (R1 fait : magasins, appareils, mot de passe oublié, transfert de propriété ; R2 → R8 à suivre), puis 3.10</td></tr><tr><td><strong>Console Vendora</strong> (éditeur)</td><td>Équipe Vendora et double authentification, clients et essai libre, formules et limites appliquées par le serveur, cycle de vie sans couper la vente, support en lecture seule tracée, supervision, factures et avoirs, devis, paramètres de facturation, emails SMTP, tarifs publics</td><td><span class="badge ok">Fait</span> 31/10/2026 (lots C1 → C6) — restent des valeurs à fournir (<a href="/VendoraSystem-docs/applications/console">mise en production</a>)</td></tr><tr><td><strong>4 — Kiosque, white-label, scale</strong></td><td>Application kiosque, branding complet, profils vêtements / épicerie (variantes, poids, péremption), onboarding guidé et paiement en ligne récurrent (la facturation des clients est faite dans la console), API publique, canaux clients (menu QR, commande en ligne, click &amp; collect), El Fatoora</td><td><span class="badge todo">À faire</span></td></tr><tr><td><strong>Terrain (en parallèle)</strong></td><td>Homologation <strong>NACEF</strong> (cahier des charges à récupérer depuis la Tunisie), comptes marchands <strong>Flouci / Konnect</strong>, certification <strong>NF525 / LNE</strong>, plateforme agréée e-reporting, validations sur matériel physique</td><td><span class="badge blocked">Bloqué (terrain)</span></td></tr></tbody></table><p>Détail lot par lot : <a href="/VendoraSystem-docs/suivi/journal">journal des lots</a> · ce qui reste : <a href="/VendoraSystem-docs/suivi/reste-a-faire">reste à faire</a>.</p>',3)])])}const g=t(o,[["render",i]]);export{m as __pageData,g as default};
